from typing import Any, Optional

logger = logging.getLogger(__name__)

# Security: Default trusted directories for external tools
# Can be overridden via CODEX_TRUSTED_TOOL_DIRS environment variable
DEFAULT_TRUSTED_DIRS = ["/usr/bin", "/usr/local/bin", "/opt/homebrew/bin"]
TRUSTED_TOOL_DIRS = os.environ.get("CODEX_TRUSTED_TOOL_DIRS", "").split(":") if os.environ.get("CODEX_TRUSTED_TOOL_DIRS") else DEFAULT_TRUSTED_DIRS

# Safeguards: Configuration bounds
MAX_FILE_SIZE_KB = 1024
MAX_FILES_TO_ANALYZE = 1000
from inspect import signature as _mutmut_signature
from typing import Annotated
from typing import Callable
from typing import ClassVar


MutantDict = Annotated[dict[str, Callable], "Mutant"]


def _mutmut_trampoline(orig, mutants, call_args, call_kwargs, self_arg = None):
    """Forward call to original or mutated function, depending on the environment"""
    import os
    mutant_under_test = os.environ['MUTANT_UNDER_TEST']
    if mutant_under_test == 'fail':
        from mutmut.__main__ import MutmutProgrammaticFailException
        raise MutmutProgrammaticFailException('Failed programmatically')      
    elif mutant_under_test == 'stats':
        from mutmut.__main__ import record_trampoline_hit
        record_trampoline_hit(orig.__module__ + '.' + orig.__name__)
        result = orig(*call_args, **call_kwargs)
        return result
    prefix = orig.__module__ + '.' + orig.__name__ + '__mutmut_'
    if not mutant_under_test.startswith(prefix):
        result = orig(*call_args, **call_kwargs)
        return result
    mutant_name = mutant_under_test.rpartition('.')[-1]
    if self_arg is not None:
        # call to a class method where self is not bound
        result = mutants[mutant_name](self_arg, *call_args, **call_kwargs)
    else:
        result = mutants[mutant_name](*call_args, **call_kwargs)
    return result


@dataclass
class LintIssue:
    """A linting issue found in source code."""
    rule: str
    severity: str  # error, warning, info
    line: int
    column: int
    message: str
    file_path: str


@dataclass
class SecurityIssue:
    """A security issue found in source code."""
    tool: str  # bandit, semgrep, gitleaks
    rule_id: str
    severity: str  # critical, high, medium, low
    line: int
    message: str
    file_path: str


@dataclass
class ComplexityMetrics:
    """Complexity metrics for a file."""
    cyclomatic: float
    cognitive: float
    halstead_difficulty: Optional[float] = None


@dataclass
class FileAnalysis:
    """Analysis results for a single file."""
    path: str
    loc: int
    sloc: int
    complexity: ComplexityMetrics
    imports: list[str]
    exports: list[str]
    lint_issues: list[LintIssue]
    security_issues: list[SecurityIssue]


@dataclass
class StaticReport:
    """Complete static analysis report.

    Contains analysis results for all files in the source directory
    along with aggregate statistics.
    """
    snapshot_id: str
    timestamp: datetime
    files: list[FileAnalysis]
    summary: dict[str, Any]

    def to_dict(self) -> dict[str, Any]:
        """Convert report to dictionary for JSON serialization."""
        return {
            "snapshot_id": self.snapshot_id,
            "timestamp": self.timestamp.isoformat(),
            "files": [
                {
                    "path": f.path,
                    "loc": f.loc,
                    "sloc": f.sloc,
                    "complexity": {
                        "cyclomatic": f.complexity.cyclomatic,
                        "cognitive": f.complexity.cognitive,
                        "halstead_difficulty": f.complexity.halstead_difficulty,
                    },
                    "imports": f.imports,
                    "exports": f.exports,
                    "lint_issues": [
                        {
                            "rule": i.rule,
                            "severity": i.severity,
                            "line": i.line,
                            "message": i.message,
                        }
                        for i in f.lint_issues
                    ],
                    "security_issues": [
                        {
                            "tool": s.tool,
                            "rule_id": s.rule_id,
                            "severity": s.severity,
                            "line": s.line,
                            "message": s.message,
                        }
                        for s in f.security_issues
                    ],
                }
                for f in self.files
            ],
            "summary": self.summary,
        }

    def save(self, path: Path) -> None:
        """Save report to JSON file."""
        with path.open("w", encoding="utf-8") as f:
            json.dump(self.to_dict(), f, indent=2)


def x__count_lines__mutmut_orig(content: str) -> tuple[int, int]:
    """Count total and source lines of code.

    Returns:
        tuple of (total_loc, source_loc)
    """
    lines = content.split("\n")
    loc = len(lines)

    # Count non-empty, non-comment lines
    sloc = 0
    in_docstring = False
    for line in lines:
        stripped = line.strip()

        # Handle docstrings
        if '"""' in stripped or "'''" in stripped:
            count = stripped.count('"""') + stripped.count("'''")
            if count == 1:
                in_docstring = not in_docstring
            continue

        if in_docstring:
            continue

        # Skip empty lines and comments
        if stripped and not stripped.startswith("#"):
            sloc += 1

    return loc, sloc


